const businessContextVersions = `-- name: BusinessContextVersions :many
SELECT v.id, v.organization_id, v.section_id, v.revision, v.kind, v.title, v.body, v.active, v.sort_order, v.updated_by, v.created_at, v.updated_at FROM business_context_versions v JOIN business_context_sections s ON s.organization_id=v.organization_id AND s.id=v.section_id
WHERE v.organization_id=$1 AND s.uuid=$2 ORDER BY v.revision DESC LIMIT $3 OFFSET $4
`

type BusinessContextVersionsParams struct {
	OrganizationID int64     `json:"organization_id"`
	Uuid           uuid.UUID `json:"uuid"`
	Limit          int32     `json:"limit"`
	Offset         int32     `json:"offset"`
}

func (q *Queries) BusinessContextVersions(ctx context.Context, arg BusinessContextVersionsParams) ([]BusinessContextVersion, error) {
	rows, err := q.db.Query(ctx, businessContextVersions,
		arg.OrganizationID,
		arg.Uuid,
		arg.Limit,
		arg.Offset,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []BusinessContextVersion{}
	for rows.Next() {
		var i BusinessContextVersion
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.SectionID,
			&i.Revision,
			&i.Kind,
			&i.Title,
			&i.Body,
			&i.Active,
			&i.SortOrder,
			&i.UpdatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

