const knowledgeReviewDueOrganizations = `-- name: KnowledgeReviewDueOrganizations :many
SELECT DISTINCT a.organization_id FROM knowledge_articles a WHERE a.deleted_at IS NULL AND a.updated_at<now()-interval '6 months'
AND NOT EXISTS(SELECT 1 FROM knowledge_reviews r WHERE r.organization_id=a.organization_id AND r.article_id=a.id AND r.article_version=a.version AND r.reason='age')
UNION
SELECT t.organization_id FROM knowledge_translations t
JOIN knowledge_articles source ON source.organization_id=t.organization_id AND source.id=t.source_article_id
JOIN knowledge_articles target ON target.organization_id=t.organization_id AND target.id=t.target_article_id
WHERE target.deleted_at IS NULL AND source.version>t.source_version
AND NOT EXISTS(SELECT 1 FROM knowledge_reviews r WHERE r.organization_id=t.organization_id AND r.article_id=target.id AND r.article_version=target.version AND r.reason='translation_outdated')
ORDER BY organization_id LIMIT 20
`

func (q *Queries) KnowledgeReviewDueOrganizations(ctx context.Context) ([]int64, error) {
	rows, err := q.db.Query(ctx, knowledgeReviewDueOrganizations)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var organization_id int64
		if err := rows.Scan(&organization_id); err != nil {
			return nil, err
		}
		items = append(items, organization_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const knowledgeReviews = `-- name: KnowledgeReviews :many
SELECT r.id, r.uuid, r.organization_id, r.article_id, r.article_version, r.reason, r.detail, r.owner_id, r.status, r.created_at, r.updated_at,a.uuid AS article_uuid,a.title,a.locale FROM knowledge_reviews r JOIN knowledge_articles a ON a.organization_id=r.organization_id AND a.id=r.article_id
WHERE r.organization_id=$1 ORDER BY r.id DESC LIMIT $2 OFFSET $3
`

type KnowledgeReviewsParams struct {
	OrganizationID int64 `json:"organization_id"`
	Limit          int32 `json:"limit"`
	Offset         int32 `json:"offset"`
}

type KnowledgeReviewsRow struct {
	ID             int64              `json:"id"`
	Uuid           uuid.UUID          `json:"uuid"`
	OrganizationID int64              `json:"organization_id"`
	ArticleID      int64              `json:"article_id"`
	ArticleVersion int32              `json:"article_version"`
	Reason         string             `json:"reason"`
	Detail         string             `json:"detail"`
	OwnerID        int64              `json:"owner_id"`
	Status         string             `json:"status"`
	CreatedAt      pgtype.Timestamptz `json:"created_at"`
	UpdatedAt      pgtype.Timestamptz `json:"updated_at"`
	ArticleUuid    uuid.UUID          `json:"article_uuid"`
	Title          string             `json:"title"`
	Locale         string             `json:"locale"`
}

func (q *Queries) KnowledgeReviews(ctx context.Context, arg KnowledgeReviewsParams) ([]KnowledgeReviewsRow, error) {
	rows, err := q.db.Query(ctx, knowledgeReviews, arg.OrganizationID, arg.Limit, arg.Offset)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []KnowledgeReviewsRow{}
	for rows.Next() {
		var i KnowledgeReviewsRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.ArticleID,
			&i.ArticleVersion,
			&i.Reason,
			&i.Detail,
			&i.OwnerID,
			&i.Status,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ArticleUuid,
			&i.Title,
			&i.Locale,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

